    // | REFRESH               | 0       |
    // | PRECHARGE             | 1       |
    // | ACTIVATE              | 2       |
    // | READ                  | 3       |
    // | WRITE                 | 4       |
    // | SELF REFRESH ENTER    | 5       |
    // | SELF REFRESH EXIT     | 6       |
    // | UNKNOWN               | 7       |
    // +-----------------------+---------+
    //
    // Use a small packed reg to avoid wide string literal assignments
    // and the associated WIDTHEXPAND warnings.
    reg [2:0] reqType; // holds 0..7 per table above

    initial begin
        $sformat(filename, "memory_request_queue_stats_scheduler_rank%0d_bank%0d.csv", RANK, BANK);
